#!/usr/bin/env bash
# Flat-style pose sheets of the story cast (cut-outs animated over empty plates from
# tools/gen_story_plates.sh). Needs a Gemini key with image quota (paid tier).
cd "$(dirname "$0")/.."
mkdir -p art_src/story/cast
STY="Art style: EXACTLY the flat 2D animated-film style of the FIRST reference image (bold flat colour shapes, crisp clean outlines, limited palette, subtle paper grain, no glow, no 3D, no realistic lighting). The character design (face, hair, costume, colours) follows the OTHER reference image exactly. Each pose is a separate full-body figure in its own equal cell, all at the SAME SCALE, fully inside the cell with margin, no props unless named, no shadows, no ground. No text."
g() { [ -f "$1" ] || python -I tools/gen_image.py "$@" || echo "FAILED $1"; }
g art_src/story/cast/tamra.png "Pose sheet of the boy TAMRA (12 years old) for animated story cutscenes. Grid of 4 columns x 3 rows, reading order: 1) sitting cross-legged facing right, pointing his index finger forward, delighted smile. 2) standing facing right, frightened, hands up near his face. 3) facing right, screaming and crying, reaching forward with both arms. 4) falling backwards, arms flailing up. 5) sitting on the ground facing right, bruised, looking up with hope. 6) standing facing right, looking up, determined, fists clenched. 7) standing facing right holding his copper-banded staff ready. 8) kneeling facing right, looking down, surprised. 9) running facing right with the staff. 10) fierce battle stance facing right, staff raised high. 11) standing facing right, exhausted, bent forward, panting. 12) standing facing right, smiling softly, sleepy. Plain flat pure green background (#00FF00). $STY" --ref art_src/story/p01_fire.png --ref art_src/chars/hero_ref2.png --aspect 4:3 --size 2K
g art_src/story/cast/maa.png "Pose sheet of MAA, the boy's mother. Grid of 3 columns x 2 rows, reading order: 1) kneeling facing right, guiding with her index finger extended, smiling. 2) standing facing right, one arm out shielding someone behind her, looking back in panic. 3) lifted in the air, legs dangling, reaching down with both arms, crying. 4) standing facing right, hand on her heart, loving smile. 5) kneeling facing left, one hand raised high, palm open, calling out. 6) slumped sitting facing left, weak, one hand reaching forward. Plain flat pure magenta background (#FF00FF). $STY" --ref art_src/story/p01_fire.png --ref art_src/chars/maa_ref.png --aspect 3:2 --size 2K
g art_src/story/cast/king.png "Pose sheet of THE SMOKE KING. Grid of 2 columns x 2 rows: 1) standing facing left, sceptre raised high, cruel smile. 2) leaning forward facing left, pointing down. 3) facing left, arms spread wide, laughing. 4) standing facing left, arms crossed, triumphant. Robe ends in flat curls of black smoke. Plain flat pure green background (#00FF00). $STY" --ref art_src/story/p03_king.png --ref art_src/chars/king_ref.png --aspect 1:1 --size 2K
g art_src/story/cast/guard.png "Pose sheet of SMOKEBOUND SOLDIERS. Grid of 3 columns x 2 rows: 1) facing left, shouting, spear raised, torch in the other hand. 2) a YOUNG soldier, mask off, scared teenage face, sitting facing left, palms raised, begging. 3) facing right, striking a large bronze gong (gong included). 4) a hooded archer facing right drawing a bow. 5) facing left, running with spear lowered. 6) facing left, grabbing forward, menacing. Plain flat pure green background (#00FF00). $STY" --ref art_src/story/p02_raid.png --ref art_src/chars/soldier_ref.png --aspect 3:2 --size 2K
echo cast done
